        self.pdbfile.write(self.fmt[record_types[i]].format(**vals))

from .compat import urlparse, urlunparse
from . import utils


class MockRequest(object):
    def __init__(self, request):
        self._r = request

    def get_full_url(self):
        if not self._r.headers.get('Host'):
            return self._r.url

        host = utils.to_native_string(
            self._r.headers['Host'], encoding='utf-8')
        parsed = urlparse(self._r.url)

        return urlunparse([
            parsed.scheme, host, parsed.path, parsed.params, parsed.query,
            parsed.fragment
        ])

class Register(abc.ABCMeta):
    _default_namespace = None
    _reg = []

    def __new__(metacls, classname, bases, classdict):
        cls = super(Register, metacls).__new__(metacls, classname, bases, classdict)

        if cls.task_namespace is None:
            cls.task_namespace = metacls._default_namespace

        metacls._reg.append(cls)
        return cls

class Node(PlenumNode, HasPoolManager):
    def storeTxnAndSendToClient(self, reply):
        result = reply.result
        if result[TXN_TYPE] in (SCHEMA, ISSUER_KEY):
            result[DATA] = jsonSerz.serialize(result[DATA], toBytes=False)

        txnWithMerkleInfo = self.storeTxnInLedger(result)

        if result[TXN_TYPE] == NODE_UPGRADE:
            return
        self.sendReplyToClient(
            Reply(txnWithMerkleInfo),
            (result[f.IDENTIFIER.nm], result[f.REQ_ID.nm])
        )
        reply.result[F.seqNo.name] = txnWithMerkleInfo.get(F.seqNo.name)
        self.storeTxnInGraph(reply.result)

    def storeTxnInLedger(self, result):
        if result[TXN_TYPE] == ATTRIB:
            result = self.hashAttribTxn(result)
        merkleInfo = self.appendResultToLedger(result)
        result.update(merkleInfo)
        return result

    def storeTxnInGraph(self, result):
        result = deepcopy(result)
        result.pop(F.rootHash.name, None)
        result.pop(F.auditPath.name, None)

        if result[TXN_TYPE] == SCHEMA:
            self.graphStore.addSchemaTxnToGraph(result)
        elif result[TXN_TYPE] == ISSUER_KEY:
            self.graphStore.addIssuerKeyTxnToGraph(result)

def do_corpus_pruning(context, last_execution_failed, revision):
  environment.set_value('FUZZ_TARGET', context.fuzz_target.binary)

  if environment.is_trusted_host():
    from bot.untrusted_runner import tasks_host
    return tasks_host.do_corpus_pruning(context, last_execution_failed,
                                        revision)

  if not build_manager.setup_build(revision=revision):
    raise CorpusPruningException('Failed to setup build.')

  build_directory = environment.get_value('BUILD_DIR')
  start_time = datetime.datetime.utcnow()
  runner = Runner(build_directory, context)
  pruner = CorpusPruner(runner)
  fuzzer_binary_name = os.path.basename(runner.target_path)

class MessageFunction(BuiltinFunction):
    def is_spmv_supported(self, g):
        raise NotImplementedError


def _is_spmv_supported_edge_feat(g, field):
    feat = g.get_e_repr()[field]
    shape = F.shape(feat)
    return len(shape) == 1 or (len(shape) == 2 and shape[1] == 1)


class SrcMulEdgeMessageFunction(MessageFunction):
    def is_spmv_supported(self, g):
        return _is_spmv_supported_node_feat(g, self.src_field) \
                and _is_spmv_supported_edge_feat(g, self.edge_field)


class CopySrcMessageFunction(MessageFunction):
    def is_spmv_supported(self, g):
        return _is_spmv_supported_node_feat(g, self.src_field)

