class DistEvalHook(EvalHook):
    def after_train_epoch(self, runner):
        if not self.by_epoch or not self.evaluation_flag(runner):
            return

        if self.broadcast_bn_buffer:
            self._broadcast_bn_buffer(runner)

        from mmdet.apis import multi_gpu_test
        tmpdir = self.tmpdir
        if tmpdir is None:
            tmpdir = osp.join(runner.work_dir, '.eval_hook')
        results = multi_gpu_test(
            runner.model,
            self.dataloader,
            tmpdir=tmpdir,
            gpu_collect=self.gpu_collect)
        if runner.rank == 0:
            print('\n')
            key_score = self.evaluate(runner, results)
            if self.save_best:
                self.save_best_checkpoint(runner, key_score)

class PokemonCatchWorker(BaseTask):

    def work(self, response_dict=None):
        response_dict = response_dict or self.create_encounter_api_call()

        if not response_dict:
            return WorkerResult.ERROR

        responses = response_dict['responses']
        response = responses[self.response_key]
        if response[self.response_status_key] != ENCOUNTER_STATUS_SUCCESS and response[self.response_status_key] != INCENSE_ENCOUNTER_AVAILABLE:
            return WorkerResult.ERROR

        pokemon_data = response['wild_pokemon']['pokemon_data'] if 'wild_pokemon' in response else response['pokemon_data']
        pokemon = Pokemon(pokemon_data)
        is_vip = self._is_vip_pokemon(pokemon)

        self.emit_event(
            'pokemon_appeared',
            formatted='A wild {} appeared! (CP: {} IV: {} A/D/S {} NCP: {}'.format(
                pokemon.name, pokemon.cp, pokemon.iv, pokemon.iv_display,
                round(pokemon.cp_percent, 2),
            ),
            data={
                'pokemon': pokemon.name,
                'ncp': round(pokemon.cp_percent, 2),
                'cp': pokemon.cp,
                'iv': pokemon.iv,
                'iv_display': pokemon.iv_display,
            }
        )

from celery.schedules import crontab


class test_crontab_remaining_estimate:

    def crontab(self, *args, **kwargs):
        return crontab(*args, **dict(kwargs, app=self.app))

    def next_ocurrance(self, crontab, now):
        crontab.nowfun = lambda: now
        return now + crontab.remaining_estimate(now)

class GraphMLWriter(GraphML):
    def add_graph_element(self, G):
        if G.is_directed():
            default_edge_type='directed'
        else:
            default_edge_type='undirected'

        graphid=G.graph.pop('id',None)
        if graphid is None:
            graph_element = Element("graph", edgedefault=default_edge_type)
        else:
            graph_element = Element("graph",
                                    edgedefault=default_edge_type,
                                    id=graphid)

        default={}
        data=dict((k,v) for (k,v) in G.graph.items()
                  if k not in ['node_default','edge_default'])
        self.add_attributes("graph", graph_element, data, default)
        self.add_nodes(G,graph_element)
        self.add_edges(G,graph_element)

        for (xml_obj, data) in self.attributes.items():
            for (k, v, scope, default) in data:
                xml_obj.append(self.add_data(make_str(k),
                                             self.attr_type(k, scope, v),
                                             make_str(v), scope, default))

        self.xml.append(graph_element)

import numpy as np

class CocoDataset(CustomDataset):

    def _parse_ann_info(self, img_info, ann_info):
        gt_bboxes = []
        gt_labels = []
        gt_bboxes_ignore = []
        gt_masks_ann = []
        for i, ann in enumerate(ann_info):
            if ann.get('ignore', False):
                continue
            x1, y1, w, h = ann['bbox']
            inter_w = max(0, min(x1 + w, img_info['width']) - max(x1, 0))
            inter_h = max(0, min(y1 + h, img_info['height']) - max(y1, 0))
            if inter_w * inter_h == 0:
                continue
            if ann['area'] <= 0 or w < 1 or h < 1:
                continue
            if ann['category_id'] not in self.cat_ids:
                continue
            bbox = [x1, y1, x1 + w, y1 + h]
            if ann.get('iscrowd', False):
                gt_bboxes_ignore.append(bbox)
            else:
                gt_bboxes.append(bbox)
                gt_labels.append(self.cat2label[ann['category_id']])
                gt_masks_ann.append(ann['segmentation'])

from .compat import bytes
from .exceptions import InvalidHeader

_CLEAN_HEADER_REGEX_BYTE = re.compile(b'^\\S[^\\r\\n]*$|^$')
_CLEAN_HEADER_REGEX_STR = re.compile(r'^\S[^\r\n]*$|^$')


def check_header_validity(header):
    name, value = header

    if isinstance(value, bytes):
        pat = _CLEAN_HEADER_REGEX_BYTE
    else:
        pat = _CLEAN_HEADER_REGEX_STR
    try:
        if not pat.match(value):
            raise InvalidHeader("Invalid return character or leading space in header: %s" % name)
    except TypeError:
        raise InvalidHeader("Value for header {%s:%s} must be of type str or " 
                            "bytes, not %s" % (name, value, type(value)))

from app.utility.base_object import BaseObject
from app.objects.c_fact import Fact


class Planner(BaseObject):

    @property
    def unique(self):
        return self.hash(self.name)

    @property
    def display(self):
        return dict(name=self.name, module=self.module, params=self.params, description=self.description,
                    stopping_conditions=[fact.display for fact in self.stopping_conditions])

    def __init__(self, planner_id, name, module, params, stopping_conditions=None, description=None):
        super().__init__()
        self.planner_id = planner_id
        self.name = name
        self.module = module
        self.params = params
        self.description = description
        self.stopping_conditions = self._set_stopping_conditions(stopping_conditions)

    @staticmethod
    def _set_stopping_conditions(conditions):
        if conditions:
            return [Fact(trait, value) for sc in conditions for trait, value in sc.items()]
        return []

class BgzfReader(object):
    def readline(self):
        """Read a single line for the BGZF file."""
        i = self._buffer.find(self._newline, self._within_block_offset)
        if i == -1:
            data = self._buffer[self._within_block_offset:]
            self._load_block()
            if not self._buffer:
                return data
            else:
                return data + self.readline()
        elif i + 1 == len(self._buffer):
            data = self._buffer[self._within_block_offset:]
            self._load_block()
            assert data
            return data
        else:
            data = self._buffer[self._within_block_offset:i + 1]
            self._within_block_offset = i + 1
            return data

