import operator

def drop_streams(streams, kdims, keys):
    stream_params = stream_parameters(streams)
    inds, dims = zip(*[(ind, kdim) for ind, kdim in enumerate(kdims)
                       if kdim not in stream_params])
    get = operator.itemgetter(*inds)
    keys = (get(k) for k in keys)
    return dims, ([wrap_tuple(k) for k in keys] if len(inds) == 1 else list(keys))

class Status(AbstractCommand):
    def execute(self):
        if self.static:
            self.disabled('status')

        if not self.molecule._state.get('created'):
            errmsg = '{}ERROR: No instances created. Try `{} create` first.{}'
            print(errmsg.format(Fore.RED, os.path.basename(sys.argv[0]), Fore.RESET))
            sys.exit(1)

        try:
            status = self.molecule._provisioner.status()
        except CalledProcessError as e:
            print('ERROR: {}'.format(e))
            return e.returncode

        x = prettytable.PrettyTable(['Name', 'State', 'Provider'])
        x.align = 'l'

        for item in status:
            if item.state != 'not_created':
                state = Fore.GREEN + item.state + Fore.RESET
            else:
                state = item.state

            x.add_row([item.name, state, item.provider])

        print(x)
        print()
        self.molecule._print_valid_platforms()
        print()
        self.molecule._print_valid_providers()

from . import TypeSlots


class MethodDispatcherTransform(EnvTransform):
    def _dispatch_to_method_handler(self, attr_name, self_arg,
                                    is_unbound_method, type_name,
                                    node, function, arg_list, kwargs):
        method_handler = self._find_handler(
            "method_%s_%s" % (type_name, attr_name), kwargs)
        if method_handler is None:
            if (attr_name in TypeSlots.special_method_names
                    or attr_name in ['__new__', '__class__']):
                method_handler = self._find_handler(
                    "slot%s" % attr_name, kwargs)
            if method_handler is None:
                return self._handle_method(
                    node, type_name, attr_name, function,
                    arg_list, is_unbound_method, kwargs)
        if self_arg is not None:
            arg_list = [self_arg] + list(arg_list)
        if kwargs:
            result = method_handler(
                node, function, arg_list, is_unbound_method, kwargs)
        else:
            result = method_handler(
                node, function, arg_list, is_unbound_method)
        return result

from luigi import six


class BatchNotifier(object):
    def __init__(self, **kwargs):
        self._config = batch_email(**kwargs)

    def _key(self, task_name, family, unbatched_args):
        if self._config.batch_mode == 'all':
            return task_name
        elif self._config.batch_mode == 'family':
            return family
        elif self._config.batch_mode == 'unbatched_params':
            param_str = six.u(', ').join(
                six.u('{}={}').format(*kv) for kv in six.iteritems(unbatched_args)
            )
            return six.u('{}({})').format(family, param_str)
        else:
            raise ValueError('Unknown batch mode for batch notifier: {}'.format(
                self._config.batch_mode))
